function render(locale, x) {
  const table = (headers, rows) => `| ${headers.join(' | ')} |\n| ${headers.map(() => '---').join(' | ')} |\n${rows.map(r => `| ${r.join(' | ')} |`).join('\n')}`;
  return `---\ntitle: ${JSON.stringify(x.title)}\ndescription: ${JSON.stringify(x.description)}\nappendBrandToTitle: false\ntags: ${JSON.stringify(x.tags)}\npubDate: "${date}"\nheroImage: "${image}"\nauthor: "Seedance Team"\ntranslationKey: "${slug}"\nlang: "${locale}"\n---\n\n![${x.alt}](${image})\n\n${x.intro}\n\n> ${x.note}\n\n## ${x.updateH}\n\n${x.updateIntro}\n\n${table(x.updateHeaders, x.updateRows)}\n\n${x.updateOutro}\n\n## ${x.usesH}\n\n${x.uses.map(([h,p]) => `### ${h}\n\n${p}`).join('\n\n')}\n\n## ${x.tutorialH}\n\n${x.steps.map(([h,p]) => `### ${h}\n\n${p}`).join('\n\n')}\n\n## ${x.issuesH}\n\n${table(x.issueHeaders, x.issueRows)}\n\n## ${x.startH}\n\n${x.start}\n\n<div style="text-align:center; margin:2.5rem 0;">\n  <a href="https://app.seedance22.com/${locale}/generate/video-tools/seedance/" target="_blank" rel="noopener noreferrer" style="display:inline-block; padding:1rem 2rem; background:linear-gradient(135deg,#7c3aed 0%,#ec4899 55%,#f59e0b 100%); color:#fff; font-weight:800; font-size:1.125rem; border-radius:9999px; text-decoration:none; box-shadow:0 10px 30px rgba(124,58,237,.35);">${x.cta}</a>\n</div>\n\n${x.closing}\n`;
}

for (const [locale, content] of Object.entries(L)) {
  const out = path.join(root, 'src/content/blog', locale, `${slug}.md`);
  await fs.mkdir(path.dirname(out), { recursive: true });
  await fs.writeFile(out, render(locale, content), 'utf8');
  console.log(`generated ${locale}`);
}
